{"action":"write_file","path":"controller.js","content":"// Value-oriented scheduler with battery and hostile-robot aware navigation.
function act(o,memory){
 const W=o.width,H=o.height,map=o.map,me=o.courier,t=o.tick,J=o.jobs,D=[['N',0,-1],['E',1,0],['S',0,1],['W',-1,0]],K=(x,y)=>y*W+x,F=(x,y)=>x>=0&&y>=0&&x<W&&y<H&&map[y][x]!='#';
 let m=memory||{plan:[],trail:[],planTick:-99};if(!m.trail)m.trail=[];
 function bfs(x,y){let d=new Int16Array(W*H);d.fill(-1);let q=new Int16Array(W*H),a=0,b=0,s=K(x,y);d[s]=0;q[b++]=s;while(a<b){let k=q[a++],x=k%W,y=k/W|0,n=d[k]+1;for(const z of D){let X=x+z[1],Y=y+z[2],h=K(X,Y);if(F(X,Y)&&d[h]<0)d[h]=n,q[b++]=h;}}return d;}
 function plan(){
  let P=[{x:me.x,y:me.y}];for(const j of J)P.push(j.from,j.to);let B=P.map(p=>bfs(p.x,p.y)),dist=(i,p)=>B[i][K(p.x,p.y)];
  let st=J.map(j=>j.status==='available'?0:j.status==='carried'?1:j.status==='delivered'?2:3),wt=0,val=0;for(let i=0;i<J.length;i++){if(st[i]===1)wt+=J[i].weight;if(st[i]===2)val+=J[i].value;}
  let best=[],bs=val*10000-t,nodes=0;
  function go(pi,s,w,now,seq,v){
   if(++nodes>60000)return;let potential=v;for(let i=0;i<J.length;i++)if(s[i]<2)potential+=J[i].value;let sc=v*10000-now;if(sc>bs){bs=sc;best=seq.slice();}if(potential*10000-now<=bs)return;
   for(let i=0;i<J.length;i++){let j=J[i];if(s[i]===0){
    // Avoid the costly >3 carrying tier unless this is the only parcel aboard.
    let can=w+j.weight<=o.cargoCapacity&&(w===0||w+j.weight<=3);if(!can)continue;let d=dist(pi,j.from),nt=now+d+1;if(d<0||nt>j.deadline)continue;
    s[i]=1;seq.push({type:'pickup',id:j.id,x:j.from.x,y:j.from.y});go(1+2*i,s,w+j.weight,nt,seq,v);seq.pop();s[i]=0;
   }else if(s[i]===1){let d=dist(pi,j.to),nt=now+d+1;if(d<0||nt>j.deadline)continue;let ch=[],gain=0,nw=w;for(let k=0;k<J.length;k++)if(s[k]===1&&J[k].to.x===j.to.x&&J[k].to.y===j.to.y){s[k]=2;ch.push(k);gain+=J[k].value;nw-=J[k].weight;}seq.push({type:'deliver',x:j.to.x,y:j.to.y});go(2+2*i,s,nw,nt,seq,v+gain);seq.pop();for(const k of ch)s[k]=1;}}
  }go(0,st,wt,t,[],val);m.planTick=t;return best;
 }
 const valid=p=>p&&(p.type==='pickup'?J.some(j=>j.id===p.id&&j.status==='available'):p.type==='deliver'&&me.cargo.some(id=>{let j=J.find(x=>x.id===id);return j&&j.to.x===p.x&&j.to.y===p.y;}));
 let p=m.plan&&m.plan[0];if(!valid(p)||t-m.planTick>=8){m.plan=plan();p=m.plan[0];}if(!p)return{action:{type:'wait'},memory:m};
 const E=o.enemies,moves=e=>t%(e.period||(e.kind==='hunter'?2:3))===0;
 function unsafe(x,y){for(const e of E){let d=Math.abs(e.x-x)+Math.abs(e.y-y);if(!d||moves(e)&&d<=1)return true;}return false;}
 function danger(x,y){let v=0;for(const e of E){let d=Math.abs(e.x-x)+Math.abs(e.y-y);if(d<=1)v+=9999;else if(d===2)v+=e.kind==='hunter'?55:28;else if(d===3)v+=e.kind==='hunter'?18:9;else if(d===4)v+=4;}return v;}
 function remember(){m.trail.push(K(me.x,me.y));if(m.trail.length>12)m.trail.shift();}
 if(me.x===p.x&&me.y===p.y&&!unsafe(me.x,me.y)){let a=p.type==='pickup'?{type:'pickup',id:p.id}:{type:'deliver'};m.plan.shift();remember();return{action:a,memory:m};}
 let here=bfs(me.x,me.y),C=o.chargers,near=null,cd=999;for(const c of C){let d=here[K(c.x,c.y)];if(d>=0&&d<cd)cd=d,near=c;}
 let wt=0;for(const id of me.cargo){let j=J.find(q=>q.id===id);if(j)wt+=j.weight;}let cost=wt>3?2:1,at=C.some(c=>c.x===me.x&&c.y===me.y),gd=here[K(p.x,p.y)],fg=bfs(p.x,p.y),gc=999;for(const c of C){let d=fg[K(c.x,c.y)];if(d>=0&&d<gc)gc=d;}
 let need=(Math.max(0,gd)+Math.max(0,gc))*cost+10,target=p;
 // On reaching a charger with low reserves, take several charges before departing.
 if(at&&me.battery<88&&(me.battery<62||me.battery<need)&&!unsafe(me.x,me.y))return{action:{type:'charge'},memory:m};
 // A generous reserve pays for evasion and doorway detours.
 if(!at&&(me.battery<=cd*cost+18||(me.battery<need&&cd+4<gd)))target=near||p;
 // If carrying a nearby heavy parcel, unloading can be safer than a long charger detour.
 if(wt>3){let bp=null,bd=999;for(const id of me.cargo){let j=J.find(q=>q.id===id),d=here[K(j.to.x,j.to.y)];if(d>=0&&d<bd&&d*cost+8<me.battery)bd=d,bp={x:j.to.x,y:j.to.y,type:'deliver'};}if(bp&&bd+5<cd)target=bp;}
 let td=bfs(target.x,target.y),ch=[];for(const z of D){let x=me.x+z[1],y=me.y+z[2];if(!F(x,y)||unsafe(x,y))continue;let d=td[K(x,y)];if(d<0)continue;let recent=m.trail.lastIndexOf(K(x,y)),trail=recent<0?0:(recent+1)*3;ch.push({s:d*14+danger(x,y)+trail,d:z[0]});}ch.sort((a,b)=>a.s-b.s);
 if(ch.length&&me.battery>=cost){remember();return{action:{type:'move',dir:ch[0].d},memory:m};}
 return{action:{type:'wait'},memory:m};
}
