{"action":"write_file","path":"controller.js","content":"// Value-oriented scheduler with battery and hostile-robot aware navigation.
function act(o,memory){
 const W=o.width,H=o.height,map=o.map,me=o.courier,t=o.tick,J=o.jobs,D=[['N',0,-1],['E',1,0],['S',0,1],['W',-1,0]],K=(x,y)=>y*W+x,F=(x,y)=>x>=0&&y>=0&&x<W&&y<H&&map[y][x]!='#';
 let m=memory||{plan:[],trail:[],planTick:-99};if(!m.trail)m.trail=[];
 function bfs(x,y){let d=new Int16Array(W*H);d.fill(-1);let q=new Int16Array(W*H),a=0,b=0,s=K(x,y);d[s]=0;q[b++]=s;while(a<b){let k=q[a++],x=k%W,y=k/W|0,n=d[k]+1;for(const z of D){let X=x+z[1],Y=y+z[2],h=K(X,Y);if(F(X,Y)&&d[h]<0)d[h]=n,q[b++]=h;}}return d;}
 function plan(){
  let P=[{x:me.x,y:me.y}];for(const j of J)P.push(j.from,j.to);let B=P.map(p=>bfs(p.x,p.y)),dist=(i,p)=>B[i][K(p.x,p.y)];
  let st=J.map(j=>j.status==='available'?0:j.status==='carried'?1:j.status==='delivered'?2:3),wt=0,val=0;for(let i=0;i<J.length;i++){if(st[i]===1)wt+=J[i].weight;if(st[i]===2)val+=J[i].value;}
  let best=[],bs=val*10000-t,nodes=0;
  function go(pi,s,w,now,seq,v){
   if(++nodes>60000)return;let potential=v;for(let i=0;i<J.length;i++)if(s[i]<2)potential+=J[i].value;let sc=v*10000-now;if(sc>bs){bs=sc;best=seq.slice();}if(potential*10000-now<=bs)return;
   for(let i=0;i<J.length;i++){let j=J[i];if(s[i]===0){
    let can=w+j.weight<=o.cargoCapacity&&(w===0||w+j.weight<=3);if(!can)continue;let d=dist(pi,j.from),nt=now+d+1;if(d<0||nt>j.deadline)continue;
    s[i]=1;seq.push({type:'pickup',id:j.id,x:j.from.x,y:j.from.y});go(1+2*i,s,w+j.weight,nt,seq,v);seq.pop();s[i]=0;
   }else if(s[i]===1){let d=dist(pi,j.to),nt=now+d+1;if(d<0||nt>j.deadline)continue;let ch=[],gain=0,nw=w;for(let k=0;k<J.length;k++)if(s[k]===1&&J[k].to.x===j.to.x&&J[k].to.y===j.to.y){s[k]=2;ch.push(k);gain+=J[k].value;nw-=J[k].weight;}seq.push({type:'deliver',x:j.to.x,y:j.to.y});go(2+2*i,s,nw,nt,seq,v+gain);seq.pop();for(const k of ch)s[k]=1;}}
  }go(0,st,wt,t,[],val);m.planTick=t;return best;
 }
 const valid=p=>p&&(p.type==='pickup'?J.some(j=>j.id===p.id&&j.status==='available'):p.type==='deliver'&&me.cargo.some(id=>{let j=J.find(x=>x.id===id);return j&&j.to.x===p.x&&j.to.y===p.y;}));
 let p=m.plan&&m.plan[0];if(!valid(p)||t-m.planTick>=8){m.plan=plan();p=m.plan[0];}
 // Never become inert merely because all deadline-feasible schedules disappeared.
 if(!p){let c=J.filter(j=>j.status==='carried').sort((a,b)=>a.deadline-b.deadline)[0];if(c)p={type:'deliver',x:c.to.x,y:c.to.y};else{let a=J.filter(j=>j.status==='available').sort((a,b)=>(a.deadline-t)/(a.value+2)-(b.deadline-t)/(b.value+2))[0];if(a)p={type:'pickup',id:a.id,x:a.from.x,y:a.from.y};}}
